-- ===== Crownfall part 11: keep castles, camps and strongholds on land =====
-- Each realm gets a 100 x 100 land map traced from its painting (water, lava and mountains are blocked).

ALTER TABLE realms ADD COLUMN IF NOT EXISTS land_mask text;
UPDATE realms SET land_mask = '' WHERE id = 'realm-1';
UPDATE realms SET land_mask = '' WHERE id = 'realm-2';
UPDATE realms SET land_mask = '' WHERE id = 'realm-3';

-- ===== 11b: land helpers (x, y are map squares 0-99) =====

CREATE OR REPLACE FUNCTION cf_is_land(p_realm text, x int, y int) RETURNS boolean
LANGUAGE plpgsql STABLE AS $$
DECLARE m text; idx int; nib int;
BEGIN
  IF x < 2 OR y < 2 OR x > 97 OR y > 97 THEN RETURN false; END IF;
  SELECT land_mask INTO m FROM realms WHERE id = p_realm;
  IF m IS NULL OR length(m) < 2500 THEN RETURN true; END IF;
  idx := y * 100 + x;
  nib := position(substr(m, idx / 4 + 1, 1) IN '0123456789abcdef') - 1;
  RETURN ((nib >> (3 - idx % 4)) & 1) = 0;
END $$;

-- A castle needs its square and the eight around it to be land.
CREATE OR REPLACE FUNCTION cf_spot_ok(p_realm text, x int, y int) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT bool_and(cf_is_land(p_realm, x + dx, y + dy))
    FROM generate_series(-1, 1) dx, generate_series(-1, 1) dy
$$;

-- A random open spot on land, clear of other castles, strongholds, camps, landmarks and world sites.
CREATE OR REPLACE FUNCTION cf_random_castle_spot(p_realm text, OUT px int, OUT py int)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public AS $$
DECLARE x int; y int; i int;
BEGIN
  FOR i IN 1..400 LOOP
    x := 6 + floor(random() * 88)::int;
    y := 6 + floor(random() * 88)::int;
    CONTINUE WHEN NOT cf_spot_ok(p_realm, x, y);
    CONTINUE WHEN EXISTS (SELECT 1 FROM players WHERE home_realm_id = p_realm
                            AND abs(pos_x / 14 - x) < 3 AND abs(pos_y / 14 - y) < 3);
    CONTINUE WHEN EXISTS (SELECT 1 FROM strongholds WHERE home_realm_id = p_realm
                            AND abs(pos_x / 14 - x) < 5 AND abs(pos_y / 14 - y) < 5);
    CONTINUE WHEN EXISTS (SELECT 1 FROM world_nodes WHERE abs(map_x - x) < 3 AND abs(map_y - y) < 3);
    CONTINUE WHEN EXISTS (SELECT 1 FROM landmarks WHERE realm_id = p_realm
                            AND abs(map_x - x) < 4 AND abs(map_y - y) < 4);
    px := x * 14 + 7; py := y * 14 + 7;
    RETURN;
  END LOOP;
  -- crowded realm: settle for any land spot
  FOR i IN 1..400 LOOP
    x := 4 + floor(random() * 92)::int;
    y := 4 + floor(random() * 92)::int;
    IF cf_is_land(p_realm, x, y) THEN px := x * 14 + 7; py := y * 14 + 7; RETURN; END IF;
  END LOOP;
  px := 700; py := 700;
END $$;

-- ===== 11c: castles, strongholds and camps only on land =====

CREATE OR REPLACE FUNCTION relocate_kingdom(p_x int, p_y int) RETURNS players
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  p players := cf_me_for_update();
  r realms;
BEGIN
  SELECT * INTO r FROM realms WHERE id = p.home_realm_id;
  IF p_x NOT BETWEEN 0 AND r.map_width - 1 OR p_y NOT BETWEEN 0 AND r.map_height - 1 THEN
    RAISE EXCEPTION 'That location is outside the realm.';
  END IF;
  IF NOT cf_spot_ok(r.id, p_x / 14, p_y / 14) THEN
    RAISE EXCEPTION 'You can''t build there: pick open ground away from water, lava and mountains.';
  END IF;
  IF p.gold < 150 THEN RAISE EXCEPTION 'Need 150 Gold to relocate your Keep.'; END IF;
  IF EXISTS (SELECT 1 FROM players WHERE home_realm_id = p.home_realm_id
             AND abs(pos_x / 14 - p_x / 14) < 2 AND abs(pos_y / 14 - p_y / 14) < 2 AND id <> p.id) THEN
    RAISE EXCEPTION 'Too close to another castle.';
  END IF;
  UPDATE players SET gold = gold - 150, pos_x = p_x, pos_y = p_y
  WHERE id = p.id RETURNING * INTO p;
  RETURN p;
END $$;

CREATE OR REPLACE FUNCTION create_player(p_username text, p_realm_id text DEFAULT NULL)
RETURNS players
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid   uuid := auth.uid();
  v_realm realms;
  v_row   players;
  v_x int; v_y int;
  v_try int := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not signed in';
  END IF;

  SELECT * INTO v_row FROM players WHERE id = v_uid;
  IF FOUND THEN
    RETURN v_row;
  END IF;

  IF p_realm_id IS NOT NULL THEN
    SELECT * INTO v_realm FROM realms WHERE id = p_realm_id AND accepting_new_players;
  ELSE
    SELECT r.* INTO v_realm FROM realms r WHERE r.accepting_new_players
      ORDER BY (SELECT count(*) FROM players p WHERE p.home_realm_id = r.id), r.opened_at LIMIT 1;
  END IF;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No realm is accepting new players';
  END IF;

  SELECT s.px, s.py INTO v_x, v_y FROM cf_random_castle_spot(v_realm.id) s;

  INSERT INTO players (id, username, home_realm_id, pos_x, pos_y, shield_until)
  VALUES (
    v_uid,
    left(coalesce(nullif(trim(p_username), ''), 'Lord ' || left(v_uid::text, 6)), 28),
    v_realm.id, v_x, v_y,
    now() + interval '24 hours'
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END $$;

CREATE OR REPLACE FUNCTION found_stronghold(p_x int, p_y int, p_realm text DEFAULT NULL) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE me players := cf_me_for_update(); v_id uuid; v_near text; v_realm text;
BEGIN
  v_realm := coalesce(nullif(p_realm, ''), me.home_realm_id);
  IF v_realm <> me.home_realm_id AND NOT EXISTS (
       SELECT 1 FROM camps WHERE player_id = me.id AND realm_id = v_realm AND status = 'CAMPED') THEN
    RAISE EXCEPTION 'Set up your camp in that realm before raising a stronghold there.';
  END IF;
  IF me.alliance_role <> 'LEADER' THEN RAISE EXCEPTION 'Only the alliance leader can found a stronghold.'; END IF;
  IF EXISTS (SELECT 1 FROM strongholds WHERE alliance_id = me.alliance_id) THEN
    RAISE EXCEPTION 'Your alliance already has a stronghold.';
  END IF;
  IF p_x NOT BETWEEN 3 AND 96 OR p_y NOT BETWEEN 3 AND 96 THEN RAISE EXCEPTION 'Too close to the edge of the realm.'; END IF;
  IF NOT cf_spot_ok(v_realm, p_x, p_y) THEN
    RAISE EXCEPTION 'You can''t build there: pick open ground away from water, lava and mountains.';
  END IF;
  IF me.stone < 3000 OR me.gold < 2000 THEN RAISE EXCEPTION 'A stronghold costs 3,000 Stone and 2,000 Gold.'; END IF;

  SELECT name INTO v_near FROM world_nodes WHERE sqrt(power(map_x - p_x, 2) + power(map_y - p_y, 2)) < 4 LIMIT 1;
  IF v_near IS NOT NULL THEN RAISE EXCEPTION 'Too close to %.', v_near; END IF;
  SELECT username INTO v_near FROM players
   WHERE home_realm_id = v_realm AND sqrt(power(pos_x / 14.0 - p_x, 2) + power(pos_y / 14.0 - p_y, 2)) < 3 LIMIT 1;
  IF v_near IS NOT NULL THEN RAISE EXCEPTION 'Too close to the castle of %.', v_near; END IF;
  IF EXISTS (SELECT 1 FROM strongholds WHERE home_realm_id = v_realm
               AND sqrt(power(pos_x / 14.0 - p_x, 2) + power(pos_y / 14.0 - p_y, 2)) < 8) THEN
    RAISE EXCEPTION 'Too close to another stronghold.';
  END IF;

  UPDATE players SET stone = stone - 3000, gold = gold - 2000 WHERE id = me.id;
  INSERT INTO strongholds (alliance_id, home_realm_id, pos_x, pos_y, level, durability, max_durability)
  VALUES (me.alliance_id, v_realm, p_x * 14, p_y * 14, 1, 15000, 15000)
  RETURNING id INTO v_id;
  PERFORM cf_system_message(me.alliance_id,
    format('%s raised the alliance stronghold at (%s, %s)! Send troops to garrison it.', me.username, p_x, p_y));
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION send_expedition(p_realm text, p_x int, p_y int,
  p_infantry bigint, p_cavalry bigint, p_archers bigint, p_siege bigint) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE me players := cf_me_for_update(); v_troops jsonb; v_id uuid; v_name text;
BEGIN
  SELECT name INTO v_name FROM realms WHERE id = p_realm;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown realm.'; END IF;
  IF p_realm = me.home_realm_id THEN RAISE EXCEPTION 'Expeditions go to other realms. This is your home.'; END IF;
  IF EXISTS (SELECT 1 FROM camps WHERE player_id = me.id) THEN
    RAISE EXCEPTION 'You already have an expedition out. Recall it first.';
  END IF;
  IF p_x NOT BETWEEN 3 AND 96 OR p_y NOT BETWEEN 3 AND 96 THEN RAISE EXCEPTION 'Too close to the edge of the realm.'; END IF;
  IF NOT cf_is_land(p_realm, p_x, p_y) THEN
    RAISE EXCEPTION 'You can''t camp there: pick open ground away from water, lava and mountains.';
  END IF;
  v_troops := cf_take_troops(me, p_infantry, p_cavalry, p_archers, p_siege);
  INSERT INTO camps (player_id, realm_id, pos_x, pos_y, troops_json, troop_power, status, arrives_at)
  VALUES (me.id, p_realm, p_x * 14, p_y * 14, v_troops, cf_troop_power(v_troops), 'TRAVELING',
          now() + make_interval(secs => cf_waygate_seconds(me)))
  RETURNING id INTO v_id;
  IF me.alliance_id IS NOT NULL THEN
    PERFORM cf_system_message(me.alliance_id, left(format('%s led an expedition through the Waygate to %s.', me.username, v_name), 300));
  END IF;
  RETURN v_id;
END $$;

-- ===== 11d: move every castle that currently sits in water, lava or mountains =====
DO $$
DECLARE p record; s record; n int := 0;
BEGIN
  FOR p IN SELECT id, home_realm_id FROM players
            WHERE NOT cf_spot_ok(home_realm_id, pos_x / 14, pos_y / 14) LOOP
    SELECT * INTO s FROM cf_random_castle_spot(p.home_realm_id);
    UPDATE players SET pos_x = s.px, pos_y = s.py WHERE id = p.id;
    n := n + 1;
  END LOOP;
  RAISE NOTICE 'Moved % castles onto land', n;
END $$;

REVOKE ALL ON FUNCTION cf_random_castle_spot(text) FROM PUBLIC, anon, authenticated;
